namespace sv_090450fe76c24652a78f80111ac5e244.Models;

// Immutable submission records
public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

// Mutable form models for two-way binding
public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public WorkEntry ToRecord() =>
        new(Company, Title, StartDate ?? DateTime.Today, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

/// <summary>Stub implementation for development. Replace with a real service for production.</summary>
public class StubApplicationService : IApplicationService
{
    public async Task<int> SubmitApplicationAsync(JobApplication application)
    {
        await Task.Delay(1000);
        return Random.Shared.Next(10000, 99999);
    }

    public async Task<bool> ValidateEmailAsync(string email)
    {
        await Task.Delay(500);
        return email.Contains('@') && email.Contains('.');
    }
}

.step-indicator ol {
    gap: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-shrink: 0;
    min-width: 80px;
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s ease;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #adb5bd;
    transition: color 0.2s ease;
    white-space: nowrap;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
    cursor: pointer;
}

.step.completed .step-label {
    color: #198754;
    cursor: pointer;
}

.step.completed:hover .step-circle {
    background: #157347;
    border-color: #157347;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    align-self: flex-start;
    margin-top: 19px;
    transition: background 0.2s ease;
}

.step-connector.completed {
    background: #198754;
}

@inject IApplicationService ApplicationService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Personal Information</h4>

        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.FullName" @bind:event="oninput" placeholder="Jane Doe" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email Address <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Model.Email" @bind:event="oninput" placeholder="jane@example.com" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone Number <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.Address" @bind:event="oninput" placeholder="123 Main St, City, ST 12345" />
            </div>
        </div>

        <div class="d-flex justify-content-end mt-4">
            <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
                @if (_validating)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    <span>Validating…</span>
                }
                else
                {
                    <span>Next →</span>
                }
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private List<string> _errors = [];
    private bool _validating;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(Model.FullName))
            _errors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Model.Email))
            _errors.Add("Email address is required.");
        if (string.IsNullOrWhiteSpace(Model.Phone))
            _errors.Add("Phone number is required.");
        if (string.IsNullOrWhiteSpace(Model.Address))
            _errors.Add("Address is required.");

        if (_errors.Count > 0) return;

        _validating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                _errors.Add("The email address could not be verified. Please check and try again.");
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}

@inject IApplicationService ApplicationService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Review & Submit</h4>

        @if (_submitted)
        {
            <div class="alert alert-success text-center py-4">
                <h5 class="mb-2">✅ Application Submitted Successfully!</h5>
                <p class="mb-0">Your application ID is: <strong class="fs-4">@_applicationId</strong></p>
            </div>
        }
        else
        {
            @* ── Personal Info ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@PersonalInfo.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@PersonalInfo.Address</dd>
                </dl>
            </section>

            @* ── Work History ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-3">
                        <strong>@entry.Title</strong> at <em>@entry.Company</em><br />
                        <small class="text-muted">
                            @(entry.StartDate?.ToString("MMM yyyy") ?? "—")
                            –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "—")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0 text-muted">@entry.Description</p>
                        }
                    </div>
                }
            </section>

            @* ── References ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
                </div>
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span><br />
                        <small>@r.Email · @r.Phone</small>
                    </div>
                }
            </section>

            @* ── Cover Letter ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
                </div>
                @if (!string.IsNullOrWhiteSpace(CoverLetter))
                {
                    <p style="white-space: pre-wrap;">@CoverLetter</p>
                }
                else
                {
                    <p class="text-muted fst-italic">No cover letter provided.</p>
                }
            </section>

            @if (!string.IsNullOrEmpty(_errorMessage))
            {
                <div class="alert alert-danger">@_errorMessage</div>
            }

            <div class="d-flex justify-content-between mt-4">
                <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
                <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_submitting">
                    @if (_submitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    private async Task HandleSubmit()
    {
        _submitting = true;
        _errorMessage = null;

        try
        {
            var application = new JobApplication(
                PersonalInfo.ToRecord(),
                new WorkHistory(WorkEntries.Select(e => e.ToRecord()).ToList()),
                References.Select(r => r.ToRecord()).ToList(),
                CoverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
            await OnSubmitted.InvokeAsync(_applicationId);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _submitting = false;
        }
    }
}

