        <h4 class="card-title mb-4">Review & Submit</h4>

        @if (_submitted)
        {
            <div class="alert alert-success text-center py-4">
                <h5 class="mb-2">✅ Application Submitted Successfully!</h5>
                <p class="mb-0">Your application ID is: <strong class="fs-4">@_applicationId</strong></p>
            </div>
        }
        else
        {
            @* ── Personal Info ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Personal Information</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
                </div>
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@PersonalInfo.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@PersonalInfo.Address</dd>
                </dl>
            </section>

            @* ── Work History ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Work History</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-3">
                        <strong>@entry.Title</strong> at <em>@entry.Company</em><br />
                        <small class="text-muted">
                            @(entry.StartDate?.ToString("MMM yyyy") ?? "—")
                            –
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "—")
                        </small>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0 text-muted">@entry.Description</p>
                        }
                    </div>
                }
            </section>

            @* ── References ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">References</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
                </div>
                @foreach (var r in References)
                {
                    <div class="mb-2">
                        <strong>@r.Name</strong> <span class="text-muted">(@r.Relationship)</span><br />
                        <small>@r.Email · @r.Phone</small>
                    </div>
                }
            </section>

            @* ── Cover Letter ── *@
            <section class="mb-4">
                <div class="d-flex justify-content-between align-items-center border-bottom pb-2 mb-3">
                    <h5 class="mb-0">Cover Letter</h5>
                    <button class="btn btn-sm btn-outline-primary" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
                </div>
                @if (!string.IsNullOrWhiteSpace(CoverLetter))
                {
                    <p style="white-space: pre-wrap;">@CoverLetter</p>
                }
                else
                {
                    <p class="text-muted fst-italic">No cover letter provided.</p>
                }
            </section>

            @if (!string.IsNullOrEmpty(_errorMessage))
            {
                <div class="alert alert-danger">@_errorMessage</div>
            }

            <div class="d-flex justify-content-between mt-4">
                <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
                <button class="btn btn-success btn-lg" @onclick="HandleSubmit" disabled="@_submitting">
                    @if (_submitting)
                    {
                        <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                        <span>Submitting…</span>
                    }
                    else
                    {
                        <span>Submit Application</span>
                    }
                </button>
            </div>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter, EditorRequired] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter, EditorRequired] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnSubmitted { get; set; }

    private bool _submitting;
    private bool _submitted;
    private int _applicationId;
    private string? _errorMessage;

    private async Task HandleSubmit()
    {
        _submitting = true;
        _errorMessage = null;

        try
        {
            var application = new JobApplication(
                PersonalInfo.ToRecord(),
                new WorkHistory(WorkEntries.Select(e => e.ToRecord()).ToList()),
                References.Select(r => r.ToRecord()).ToList(),
                CoverLetter);

            _applicationId = await ApplicationService.SubmitApplicationAsync(application);
            _submitted = true;
            await OnSubmitted.InvokeAsync(_applicationId);
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}. Please try again.";
        }
        finally
        {
            _submitting = false;
        }
    }
}

