{"path": "/tmp/sv-090450fe76c24652a78f80111ac5e244/Components/Pages/ApplySteps/StepIndicator.razor", "file_text": "<nav class="step-indicator mb-4" aria-label="Application progress">
    <ol class="d-flex list-unstyled justify-content-between align-items-center m-0 p-0">
        @for (int i = 0; i < Steps.Count; i++)
        {
            var step = i + 1;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isClickable = isCompleted && !isCurrent;

            @if (i > 0)
            {
                <li class="step-connector @(CompletedSteps.Contains(step - 1) ? "completed" : "")" aria-hidden="true"></li>
            }

            <li class="step @(isCurrent ? "active" : isCompleted ? "completed" : "dimmed")"
                role="@(isClickable ? "button" : "listitem")"
                tabindex="@(isClickable ? 0 : -1)"
                @onclick="() => HandleClick(step)"
                aria-current="@(isCurrent ? "step" : null)">
                <div class="step-circle">
                    @if (isCompleted && !isCurrent)
                    {
                        <span aria-hidden="true">✓</span>
                        <span class="visually-hidden">Completed:</span>
                    }
                    else
                    {
                        @step
                    }
                </div>
                <div class="step-label">@Steps[i]</div>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter, EditorRequired] public IReadOnlyList<string> Steps { get; set; } = [];
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = [];
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private async Task HandleClick(int step)
    {
        if (CompletedSteps.Contains(step) && step != CurrentStep)
            await OnStepClicked.InvokeAsync(step);
    }
}
"}

