.step-indicator ol {
    gap: 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    flex-shrink: 0;
    min-width: 80px;
}

.step-circle {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #adb5bd;
    transition: all 0.2s ease;
}

.step-label {
    margin-top: 0.4rem;
    font-size: 0.75rem;
    text-align: center;
    color: #adb5bd;
    transition: color 0.2s ease;
    white-space: nowrap;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: #fff;
}

.step.active .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: #fff;
    cursor: pointer;
}

.step.completed .step-label {
    color: #198754;
    cursor: pointer;
}

.step.completed:hover .step-circle {
    background: #157347;
    border-color: #157347;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    align-self: flex-start;
    margin-top: 19px;
    transition: background 0.2s ease;
}

.step-connector.completed {
    background: #198754;
}

