toolArgs.file_text:
@inject IApplicationService ApplicationService

<div class="card">
    <div class="card-body">
        <h4 class="card-title mb-4">Personal Information</h4>

        @if (_errors.Count > 0)
        {
            <div class="alert alert-danger">
                <ul class="mb-0">
                    @foreach (var error in _errors)
                    {
                        <li>@error</li>
                    }
                </ul>
            </div>
        }

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Full Name <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.FullName" @bind:event="oninput" placeholder="Jane Doe" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Email Address <span class="text-danger">*</span></label>
                <input type="email" class="form-control" @bind="Model.Email" @bind:event="oninput" placeholder="jane@example.com" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Phone Number <span class="text-danger">*</span></label>
                <input type="tel" class="form-control" @bind="Model.Phone" @bind:event="oninput" placeholder="(555) 123-4567" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Address <span class="text-danger">*</span></label>
                <input class="form-control" @bind="Model.Address" @bind:event="oninput" placeholder="123 Main St, City, ST 12345" />
            </div>
        </div>

        <div class="d-flex justify-content-end mt-4">
            <button class="btn btn-primary" @onclick="HandleNext" disabled="@_validating">
                @if (_validating)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                    <span>Validating…</span>
                }
                else
                {
                    <span>Next →</span>
                }
            </button>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private List<string> _errors = [];
    private bool _validating;

    private async Task HandleNext()
    {
        _errors.Clear();

        if (string.IsNullOrWhiteSpace(Model.FullName))
            _errors.Add("Full name is required.");
        if (string.IsNullOrWhiteSpace(Model.Email))
            _errors.Add("Email address is required.");
        if (string.IsNullOrWhiteSpace(Model.Phone))
            _errors.Add("Phone number is required.");
        if (string.IsNullOrWhiteSpace(Model.Address))
            _errors.Add("Address is required.");

        if (_errors.Count > 0) return;

        _validating = true;
        try
        {
            var isValid = await ApplicationService.ValidateEmailAsync(Model.Email);
            if (!isValid)
            {
                _errors.Add("The email address could not be verified. Please check and try again.");
                return;
            }
            await OnNext.InvokeAsync();
        }
        finally
        {
            _validating = false;
        }
    }
}

