+<div class="card">
+    <div class="card-body">
+        <h4 class="card-title mb-4">Work History</h4>
+
+        @if (_errors.Count > 0)
+        {
+            <div class="alert alert-danger">
+                <ul class="mb-0">
+                    @foreach (var error in _errors)
+                    {
+                        <li>@error</li>
+                    }
+                </ul>
+            </div>
+        }
+
+        @for (int i = 0; i < Entries.Count; i++)
+        {
+            var index = i;
+            <WorkEntryEditor Entry="Entries[index]"
+                             Index="index"
+                             CanRemove="Entries.Count > 1"
+                             OnRemove="() => RemoveEntry(index)" />
+        }
+
+        <button type="button" class="btn btn-outline-secondary mb-4" @onclick="AddEntry">
+            + Add Another Position
+        </button>
+
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="OnBack">← Back</button>
+            <button class="btn btn-primary" @onclick="HandleNext">Next →</button>
+        </div>
+    </div>
+</div>
+
+@code {
+    [Parameter, EditorRequired] public List<WorkEntryModel> Entries { get; set; } = default!;
+    [Parameter] public EventCallback OnNext { get; set; }
+    [Parameter] public EventCallback OnBack { get; set; }
+
+    private List<string> _errors = [];
+
+    private void AddEntry() => Entries.Add(new WorkEntryModel());
+
+    private void RemoveEntry(int index)
+    {
+        if (Entries.Count > 1)
+            Entries.RemoveAt(index);
+    }
+
+    private async Task HandleNext()
+    {
+        _errors.Clear();
+
+        for (int i = 0; i < Entries.Count; i++)
+        {
+            var e = Entries[i];
+            if (string.IsNullOrWhiteSpace(e.Company))
+                _errors.Add($"Position {i + 1}: Company name is required.");
+            if (string.IsNullOrWhiteSpace(e.Title))
+                _errors.Add($"Position {i + 1}: Job title is required.");
+            if (e.StartDate is null)
+                _errors.Add($"Position {i + 1}: Start date is required.");
+        }
+
+        if (_errors.Count == 0)
+            await OnNext.InvokeAsync();
+    }
+}
+

